import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.Ci_RTJJ5.js";const g=JSON.parse('{"title":"Chapter format","description":"","frontmatter":{},"headers":[],"relativePath":"docs/chapter-format.md","filePath":"docs/chapter-format.md"}'),n={name:"docs/chapter-format.md"};function r(o,e,d,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="chapter-format" tabindex="-1">Chapter format <a class="header-anchor" href="#chapter-format" aria-label="Permalink to &quot;Chapter format&quot;">​</a></h1><p>Every chapter is one directory with <strong>three reader-facing documents</strong>, one grader, and one reference solution. The three documents answer three different questions and are read at three different times; merging any two of them produces a page that is simultaneously too long to work from and too thin to learn from.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chapters/NN-slug/</span></span>
<span class="line"><span>  README.md      one-screen index: goal, time, difficulty, edit list, doc links</span></span>
<span class="line"><span>  overview.md    how the mechanism works, in general. Concept + diagrams.</span></span>
<span class="line"><span>  problem.md     what you must build, what exactly is graded, and the hints.</span></span>
<span class="line"><span>  example.md     a complete, annotated implementation. Implementation-heavy.</span></span>
<span class="line"><span>  checks/        Go test suite — the only thing that defines &quot;done&quot;</span></span>
<span class="line"><span>reference/chNN/  reference implementation, cumulative, separate Go module</span></span></code></pre></div><h2 id="the-three-documents" tabindex="-1">The three documents <a class="header-anchor" href="#the-three-documents" aria-label="Permalink to &quot;The three documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><code>overview.md</code></th><th><code>problem.md</code></th><th><code>example.md</code></th></tr></thead><tbody><tr><td>Question</td><td><em>how does this work?</em></td><td><em>what must I do?</em></td><td><em>what does a full one look like?</em></td></tr><tr><td>Read when</td><td>before you start</td><td>at the keyboard</td><td>after a real attempt</td></tr><tr><td>Shape</td><td>prose, diagrams, worked byte-level examples</td><td>tables, claims, hints</td><td>code, diffs, annotations</td></tr><tr><td>Length</td><td>long, discursive</td><td>short, scannable</td><td>as long as the code</td></tr><tr><td>Spoilers</td><td>none — concept only</td><td>none</td><td>total, by design</td></tr><tr><td>Ends with</td><td>self-check questions</td><td>done-when</td><td>comparison checklist</td></tr></tbody></table><p>The rule that keeps them honest: <strong><code>overview.md</code> may not contain a working implementation, and <code>example.md</code> may not contain new concepts.</strong> If an idea only appears in the example, it belongs in the overview first.</p><h3 id="overview-md-—-the-general-doc" tabindex="-1"><code>overview.md</code> — the general doc <a class="header-anchor" href="#overview-md-—-the-general-doc" aria-label="Permalink to &quot;\`overview.md\` — the general doc&quot;">​</a></h3><p>Free-form, but must contain:</p><ol><li><strong>Why it exists</strong> — the mechanism in the domain&#39;s terms, not Go&#39;s.</li><li><strong>A diagram</strong> — <code>mermaid</code> for GitHub/HTML, plus a short ASCII version when the diagram is load-bearing, because the terminal cannot render mermaid.</li><li><strong>Real bytes</strong> — an actual SSE chunk, an actual JSON body, an actual file. Not &quot;the model returns chunks&quot;; the chunk.</li><li><strong>A failure map</strong> — the ways this goes wrong, drawn as a tree, each branch labelled with the case id that catches it. This is the link between teaching and grading.</li><li><strong>Where the real implementations go further</strong> — pi/crush/PiG file paths, and what they add that we skipped.</li><li><strong>Self-check</strong> — 3–5 questions answerable only if the concept landed, each pointing at the section that answers it.</li></ol><h3 id="problem-md-—-the-contract" tabindex="-1"><code>problem.md</code> — the contract <a class="header-anchor" href="#problem-md-—-the-contract" aria-label="Permalink to &quot;\`problem.md\` — the contract&quot;">​</a></h3><p>Fixed sections, in this order. No freestyle.</p><ol><li><strong>Your task</strong> — one sentence, naming a capability, never a function.</li><li><strong>The contract</strong> — the signature, the wire shape, the file format. Tables.</li><li><strong>What the verifier does</strong> — what it runs, and <em>that it inspects requests</em>, not only output.</li><li><strong>The verifier will assert that</strong> — one bullet per graded case, phrased as a promise, named by case id. Must match <code>checks/</code> exactly; if they diverge the checks are truth and this page is a bug.</li><li><strong>Notes</strong> — edge cases you must handle; deliberate omissions with a link to the real implementation; the output contract (stdout vs stderr, exit codes).</li><li><strong>Hints</strong> — three rungs, spoiler-collapsed, identical to <code>internal/hints</code>.</li><li><strong>Done when</strong> — <code>kata submit NN</code> green, plus one self-check sentence.</li></ol><h3 id="example-md-—-the-implementation-doc" tabindex="-1"><code>example.md</code> — the implementation doc <a class="header-anchor" href="#example-md-—-the-implementation-doc" aria-label="Permalink to &quot;\`example.md\` — the implementation doc&quot;">​</a></h3><p>The full annotated answer, structured as the <em>thinking order</em>, not the file order:</p><ol><li><strong>The shape</strong> — the function split, before any code.</li><li><strong>Steps</strong> — one section per decision, each with the code and <em>why</em>.</li><li><strong>The diffs</strong> — wrong vs right for each trap, labelled with the case id.</li><li><strong>The complete file</strong> — or a pointer to <code>reference/chNN/</code>.</li><li><strong>Production delta</strong> — a table of what pi/crush add and why we skipped it.</li><li><strong>Comparison checklist</strong> — differences that are bugs vs differences that are style.</li></ol><h2 id="which-driver" tabindex="-1">Which driver <a class="header-anchor" href="#which-driver" aria-label="Permalink to &quot;Which driver&quot;">​</a></h2><p>Each case names its driver, and the chapter&#39;s <code>problem.md</code> groups the claims by it. The rule is in <a href="./architecture.html#grading-policy">architecture.md</a>: black box by default, function level only for pure transforms with awkward inputs.</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// black box: build and run ./agent/cmd/agent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> blackbox.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(t, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(srv.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BaseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-p&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;list the files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// function level: a pinned, deliberately small surface</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">got </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SubstituteArgs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Deploy to $0 in $1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;staging&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>A case that pins a function must say so in <code>problem.md</code> under &quot;given surface&quot;, so a learner never discovers the requirement from a compile error.</p><h2 id="the-build-tag" tabindex="-1">The build tag <a class="header-anchor" href="#the-build-tag" aria-label="Permalink to &quot;The build tag&quot;">​</a></h2><p>Chapter checks carry <code>//go:build kata_checks</code>. That keeps <code>go test ./...</code> green in a fresh clone, where <code>agent/</code> is still the starter and every case is supposed to fail. <code>kata submit</code> and <code>kata verify</code> add the tag themselves, so you never pass it by hand.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tags=kata_checks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./chapters/01-chat-with-the-model/checks/</span></span></code></pre></div><h2 id="indexing" tabindex="-1">Indexing <a class="header-anchor" href="#indexing" aria-label="Permalink to &quot;Indexing&quot;">​</a></h2><p>CodeCrafters indexes stages globally with sections as headers. We do not: <strong>a chapter is the unit</strong>, <code>NN</code> is its identity, and cases inside a chapter are addressable only by case id (for hints). Inserting a chapter never renumbers a learner&#39;s progress, and the arc stays editable while it is being written.</p><h2 id="grouping-into-parts" tabindex="-1">Grouping into parts <a class="header-anchor" href="#grouping-into-parts" aria-label="Permalink to &quot;Grouping into parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Chapters</th><th>The leap</th></tr></thead><tbody><tr><td>I. Wire</td><td>01–02</td><td>talk to a model, survive its output</td></tr><tr><td>II. Act</td><td>03–04</td><td>tools, then the loop that drives them</td></tr><tr><td>III. Remember</td><td>05–07</td><td>prompt, sessions, budget</td></tr><tr><td>IV. Extend</td><td>08–09</td><td>steering, skills</td></tr><tr><td>V. Compose</td><td>10–11</td><td>subagents, MCP</td></tr></tbody></table><p>Part boundaries are where the mental model changes, and where a learner can stop and still have something useful.</p>`,27)])])}const m=t(n,[["render",r]]);export{g as __pageData,m as default};
